const l=document.getElementById("nav");window.addEventListener("scroll",()=>{l.classList.toggle("scrolled",window.scrollY>40)},{passive:!0});const o=document.getElementById("navToggle"),n=document.getElementById("mobMenu");o.addEventListener("click",()=>{const e=o.classList.toggle("open");n.classList.toggle("open",e),document.body.style.overflow=e?"hidden":""});document.querySelectorAll(".ml").forEach(e=>{e.addEventListener("click",()=>{o.classList.remove("open"),n.classList.remove("open"),document.body.style.overflow=""})});const s=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&(t.target.classList.add("in"),s.unobserve(t.target))})},{threshold:.08,rootMargin:"0px 0px -40px 0px"});document.querySelectorAll(".reveal").forEach(e=>s.observe(e));
